import { describe, expect, it } from "vitest";
import { fromHex, toHex } from "./bytes";
import { buildAirFrame, parseAirFrame, type AirFrame } from "./lanframe";
import * as p from "./protocol";

// Key, frame and tag generated by compiling the firmware's own BLAKE2s
// (firmware/lib/mlcrypto) with the computeTag() steps from firmware/src/main.cpp.
const KEY = Uint8Array.from({ length: 16 }, (_, i) => 0xa0 + i);
const GOLDEN: AirFrame = {
  type: p.AIR_DM, ttl: 0, msgId: 0x11223344, origin: 0xaabbccdd, netId: 0x01020304, flags: 1,
  body: Uint8Array.of(1, 2, 3, 4, 5),
};
const GOLDEN_TAG = "be71f48f05b23b7b";

describe("lanframe", () => {
  it("tags exactly like the firmware", () => {
    const wire = buildAirFrame(GOLDEN, KEY);
    expect(toHex(wire.subarray(wire.length - p.TAG_LEN))).toBe(GOLDEN_TAG);
  });

  it("writes the v3 header with ttl 0 and the tag after the body", () => {
    const wire = buildAirFrame(GOLDEN, KEY);
    expect(wire.length).toBe(p.AIR_HEADER_LEN + 5 + p.TAG_LEN);
    expect(toHex(wire.subarray(0, 17))).toBe("4d0302" + "00" + "44332211" + "ddccbbaa" + "04030201" + "01");
  });

  it("round-trips a frame", () => {
    const r = parseAirFrame(buildAirFrame(GOLDEN, KEY), GOLDEN.netId, KEY);
    expect(r.ok).toBe(true);
    if (r.ok) expect(r.frame).toEqual(GOLDEN);
  });

  it("accepts an empty body and a full 225-byte body", () => {
    for (const n of [0, p.MAX_BODY]) {
      const f = { ...GOLDEN, body: new Uint8Array(n).fill(7) };
      const r = parseAirFrame(buildAirFrame(f, KEY), f.netId, KEY);
      expect(r.ok && r.frame.body.length).toBe(n);
    }
  });

  it("ignores ttl when checking the tag, as relays change it", () => {
    const wire = buildAirFrame(GOLDEN, KEY);
    wire[3] = 5;
    const r = parseAirFrame(wire, GOLDEN.netId, KEY);
    expect(r.ok && r.frame.ttl).toBe(5);
  });

  it("refuses header fields that do not fit, instead of truncating them", () => {
    const bad: Partial<AirFrame>[] = [
      { msgId: 0 }, { msgId: 2 ** 32 }, { msgId: 1.5 }, { origin: -1 }, { origin: 2 ** 32 },
      { netId: 2 ** 32 }, { netId: -1 }, { type: 256 }, { flags: -1 }, { flags: 256 },
    ];
    for (const over of bad) expect(() => buildAirFrame({ ...GOLDEN, ...over }, KEY), JSON.stringify(over)).toThrow(/out of range/);
    expect(() => buildAirFrame({ ...GOLDEN, origin: 0, netId: 0 }, KEY)).not.toThrow(); // the open network and origin 0 are fine
  });

  it("rejects a body that does not fit", () => {
    expect(() => buildAirFrame({ ...GOLDEN, body: new Uint8Array(p.MAX_BODY + 1) }, KEY)).toThrow();
  });

  it("drops every kind of bad frame with a reason", () => {
    const good = buildAirFrame(GOLDEN, KEY);
    const reason = (d: Uint8Array, netId = GOLDEN.netId, key = KEY) => {
      const r = parseAirFrame(d, netId, key);
      return r.ok ? "ok" : r.reason;
    };
    expect(reason(good.subarray(0, p.AIR_HEADER_LEN + p.TAG_LEN - 1))).toBe("short");
    expect(reason(new Uint8Array(p.MAX_AIR + 1))).toBe("long");
    expect(reason(Uint8Array.from(good, (b, i) => (i === 0 ? 0 : b)))).toBe("magic");
    expect(reason(Uint8Array.from(good, (b, i) => (i === 1 ? 2 : b)))).toBe("version");
    expect(reason(Uint8Array.from(good, (b, i) => (i === 4 ? 0 : i >= 5 && i < 8 ? 0 : b)))).toBe("msgid");
    expect(reason(good, 0x0badf00d)).toBe("foreign");
    expect(reason(good, GOLDEN.netId, new Uint8Array(16))).toBe("tag");
    const flipBody = Uint8Array.from(good);
    flipBody[p.AIR_HEADER_LEN] ^= 1;
    expect(reason(flipBody)).toBe("tag");
    const flipTag = Uint8Array.from(good);
    flipTag[flipTag.length - 1] ^= 1;
    expect(reason(flipTag)).toBe("tag");
    const flipOrigin = Uint8Array.from(good);
    flipOrigin[8] ^= 1;
    expect(reason(flipOrigin)).toBe("tag");
  });

  it("checks the foreign network before the tag, so another network's key is never needed", () => {
    const other = buildAirFrame({ ...GOLDEN, netId: 0x77 }, fromHex("00".repeat(15) + "01"));
    const r = parseAirFrame(other, GOLDEN.netId, KEY);
    expect(r.ok ? "ok" : r.reason).toBe("foreign");
  });
});
